def rrf(*ranked_lists, k=60):
    scores = {}
    for docs in ranked_lists:
        for rank, d in enumerate(docs):
            scores[d.page_content] = scores.get(d.page_content, 0) + 1 / (k + rank + 1)
    return sorted(scores, key=scores.get, reverse=True)

