from typing import Annotated
from langchain_core.tools import tool
from langgraph.prebuilt import InjectedState

@tool
def lookup_order(order_id: str, state: Annotated[dict, InjectedState]) -> str:
    """Fetch an order. order_id looks like 'ORD-1042'."""
